(window.LADDER_CARDS=window.LADDER_CARDS||{})["23·nav"]=[{"q": "The line of sight to the horizon touches the sea at T. What makes the right corner?", "a": "the sight line is square to the radius CT", "w": ["the eye is straight above T", "the sea is flat near T", "the sight line is level"], "why": "Tangent square to radius (21q)."}, {"q": "(R + h)² = R² + d². What is d?", "a": "the length of the sight line to the horizon", "w": ["the distance over the water", "the height of the eye", "the earth’s radius"], "why": "The right-triangle technique in C, T and the eye."}, {"q": "d = √(2Rh + h²) is read as √(2Rh). What is dropped?", "a": "the h² term, worth a share under h/(4R)", "w": ["the 2Rh term", "the earth’s radius", "the bending of the air"], "why": "The horizon technique: √(2Rh) ≤ d ≤ √(2Rh)(1 + h/(4R))."}, {"q": "An eye is raised from 5 m to 20 m. What happens to the horizon distance?", "a": "it doubles", "w": ["it quadruples", "it rises by 15 km", "it stays the same"], "why": "The distance goes as √h."}, {"q": "A lamp at h₁ and an eye at h₂. At about what distance does the lamp first show?", "a": "√(2Rh₁) + √(2Rh₂)", "w": ["√(2R(h₁ + h₂))", "√(2Rh₁) − √(2Rh₂)", "√(2Rh₁h₂)"], "why": "Two sight lines meet at one grazing point, each with its own root."}, {"q": "Which is shorter: the sight line d or the distance s over the water?", "a": "s, the distance over the water", "w": ["d, the sight line", "they are equal", "it depends on the air"], "why": "s = Rφ ≤ R tan φ = d, by the small-arc technique."}, {"q": "A circle of radius ρ falls x²/(2ρ) below its tangent at distance x. What is this called on the page?", "a": "the sag", "w": ["the dip", "the horizon", "the parallax"], "why": "ρ − √(ρ² − x²), with its tiny term dropped."}, {"q": "The air bends the sight line along a circle of radius ρ. As what does the sea then look?", "a": "a ball of radius R′, with 1/R′ = 1/R − 1/ρ", "w": ["a ball of radius R + ρ", "a ball of radius ρ", "a ball of radius R, unchanged"], "why": "Subtract the two sags: x²/(2R) − x²/(2ρ) = x²/(2R′)."}, {"q": "With ordinary bending, ρ ≈ 7R. How much farther is the horizon?", "a": "about 8 percent", "w": ["about 14 percent", "about 1 percent", "about 17 percent"], "why": "R′ = 7R/6, and √(7/6) ≈ 1.08."}, {"q": "ρ = R. What does an eye near the sea see?", "a": "the sea as flat, with no horizon from the curve", "w": ["the horizon at √(2Rh)", "the horizon at half the usual distance", "nothing past its feet"], "why": "1/R′ = 0: the sight line runs along the curve of the sea."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["27·nav"]=[{"q": "A signal’s delay is off by one billionth of a second. The distance is off by about …", "a": "30 cm", "w": ["3 m", "300 m", "3 cm"], "why": "The travel-time technique: c times 10⁻⁹ s is about 0.3 m."}, {"q": "A phone’s clock is a thousandth of a second ahead. Each measured distance is …", "a": "about 300 km too long", "w": ["about 300 m too long", "about 300 km too short", "unchanged"], "why": "Each delay is 10⁻³ s too long, and c · 10⁻³ s ≈ 300 km."}, {"q": "|X − S₂|² = r₂² less |X − S₁|² = r₁². What is left?", "a": "a straight sameness in X", "w": ["a sphere", "a quadratic in X", "nothing: they cancel"], "why": "The sphere-difference technique: |X|² cancels."}, {"q": "ρᵢ = |X − Sᵢ| + b. What is b?", "a": "the phone’s clock error, as a distance", "w": ["the satellite’s height", "the earth’s radius", "a different error for each satellite"], "why": "The same b for every satellite: c times the clock error."}, {"q": "Why does a phone need a fourth satellite?", "a": "its clock error is a fourth unknown", "w": ["the earth is a ball", "three spheres never meet", "each satellite gives two samenesses"], "why": "The clock-unknown technique: x, y, z and b."}, {"q": "Four spheres, subtracted in pairs, give three straight samenesses in x, y, z and b. Their answers form …", "a": "a line, p + bq", "w": ["one point", "a plane", "nothing"], "why": "Three samenesses, four unknowns: one left free."}, {"q": "What picks the fix out of the line p + bq?", "a": "one sphere, by a quadratic in b", "w": ["a fifth straight sameness", "the determinant", "the clock alone"], "why": "Put p + bq into |X − S₁|² = (ρ₁ − b)²."}, {"q": "The quadratic gives b ≈ 85 and b ≈ 57 000. The second root puts X 10 117 km from the earth’s centre. It is …", "a": "thrown out: not on the ground", "w": ["the true fix", "the clock error", "a second phone"], "why": "Only one root lies near the ground."}, {"q": "Three towers nearly on one road. det M of the straight samenesses is …", "a": "near 0, so small errors move the fix far", "w": ["large, so the fix is sharp", "exactly 1", "unchanged by where the towers stand"], "why": "The spread-sky technique: the miss is M⁻¹ times the error."}, {"q": "Satellites bunched in one patch of sky. A phone should report …", "a": "its fix with a wide circle", "w": ["its fix to the metre", "no fix at all", "a fix with no circle"], "why": "The cloud: a fix is a fence, stretched by how the satellites stand."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29·nav"]=[{"q": "The north pole, Seattle and Tokyo, joined by great circles, make …", "a": "a triangle on the sphere, with angle at the pole the gap in longitude", "w": ["a flat triangle with angles adding to π", "a lune between two great circles", "a triangle whose sides are lines of latitude"], "why": "29i’s triangle: sides π/2 − φ from the pole."}, {"q": "Tokyo lies south of Seattle. The great-circle route leaves Seattle heading …", "a": "north of west, about 300°", "w": ["south of west, about 261°", "due west, 270°", "due south"], "why": "The great-circle technique gives h ≈ 59.7° west of north."}, {"q": "A straight line on the heading-keeping map of 22·nav is …", "a": "a steady heading, longer than the great circle", "w": ["the great circle, the shortest way", "a line of latitude", "a line of longitude only"], "why": "It crosses every meridian at one angle; Seattle to Tokyo it is 8158 km against 7656."}, {"q": "Along a great-circle route, what stays the same?", "a": "cos φ times sin h", "w": ["the heading h", "the latitude φ", "cos φ plus sin h"], "why": "The kept-product technique, from the sphere-sine technique on the triangle NPX."}, {"q": "Where is a great-circle route highest?", "a": "where it runs due east or west", "w": ["where it runs due north", "at its starting city", "half way along, always"], "why": "There sin h = 1, and cos φ is least: 29i’s farthest-north technique."}, {"q": "When does a great-circle route pass over the pole?", "a": "when the two cities’ longitudes differ by 180°", "w": ["whenever the far city is in Asia", "when both cities are north of 45°", "when the route is longer than 10 000 km"], "why": "The product cos φ sin h is then 0: the route leaves due north."}, {"q": "Seattle to Dubai leaves on 2.2° and reaches 88.5° N. Why so far north?", "a": "Dubai is 177.7° of longitude away, nearly opposite", "w": ["Dubai is far south", "the earth is flatter at the poles", "the steady heading runs north"], "why": "Near-opposite longitudes make sin h near 0."}, {"q": "sin H = sin φ sin δ + cos φ cos δ cos t. What is H?", "a": "the height of a star above the horizon, seen from latitude φ", "w": ["the heading of the ship", "the star’s latitude on the sky", "the gap in longitude"], "why": "The star-circle technique: 90° − H is the distance to the star’s ground point."}, {"q": "The pole star reads 48.6° above the horizon. The latitude is about …", "a": "48.6°, within about 0.6°", "w": ["41.4°", "90° − 48.6°", "48.6° exactly"], "why": "δ ≈ 89.4°, so sin H ≈ sin φ."}, {"q": "A triangle on the earth has angles adding to 202.95°. Its area is …", "a": "(22.95° in radians) × R²", "w": ["0, as for a flat triangle", "202.95 × R²", "the excess in degrees times R"], "why": "The excess-area technique (29b): area = excess × R²."}, {"q": "cos γ = 0.99999998 for two places a kilometre apart. What goes wrong at seven figures?", "a": "it rounds to 1, and the distance comes out 0", "w": ["nothing: cos is exact", "the heading flips", "the distance doubles"], "why": "The half-angle distance technique avoids subtracting two nearly equal numbers."}, {"q": "sin²(γ/2) = sin²(Δφ/2) + cos φ₁ cos φ₂ sin²(Δλ/2). What licenses its first move, 1 − cos γ = 2 sin²(γ/2)?", "a": "the half-arc technique (21k)", "w": ["the great-circle technique", "the kept-product technique", "the excess-area technique"], "why": "The half-arc technique turns 1 − cos into a square of a sine."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30·nav"]=[{"q": "Two independent fixes of widths a and b. The weight on the first should be in proportion to …", "a": "1/a²", "w": ["1/a", "a²", "a"], "why": "The weigh-by-trust technique: one over the spread."}, {"q": "The spread of the best combination is …", "a": "1/(1/a² + 1/b²)", "w": ["(a² + b²)/4", "a² + b²", "the smaller of a² and b²"], "why": "Trusts add, so the result beats either fix."}, {"q": "A satellite fix of width 2 m and a radar fix of width 10 m, weighted by trust, give a width of about …", "a": "1.96 m", "w": ["5.1 m", "6 m", "2 m exactly"], "why": "1/(1/4 + 1/100) = 3.85, width 1.96."}, {"q": "The plain average of those two fixes has width …", "a": "5.1 m", "w": ["1.96 m", "6 m", "12 m"], "why": "√104/2: worse than the satellite fix alone."}, {"q": "A plain average of two fixes beats the better one alone exactly when the worse width b is …", "a": "less than √3 times the better a", "w": ["less than 2a", "less than a", "any width"], "why": "(a² + b²)/4 < a² iff b² < 3a²."}, {"q": "n equal fixes of width s, combined, have width …", "a": "s/√n", "w": ["s/n", "s", "s√n"], "why": "Trusts add; 30q’s sample-average technique."}, {"q": "Between fixes, a carried position’s spread …", "a": "grows by q each minute, like a random walk", "w": ["stays at its last fix’s spread", "shrinks with time", "grows like t²"], "why": "The predict step: 30n’s root-n technique."}, {"q": "In the predict-and-correct technique, the spread just after each fix settles where …", "a": "P² + qtP − qtR = 0", "w": ["P = R", "P = qt", "P = 0"], "why": "A steady saw tooth."}, {"q": "Errors east and north are independent bells of width σ. The chance of being more than r off is …", "a": "e^(−r²/(2σ²))", "w": ["e^(−r/σ)", "r/σ", "1 − r²/σ²"], "why": "The circle-chance technique, by distance and turn (28i)."}, {"q": "A 95% circle of radius 4.9 m means each direction has width about …", "a": "2.0 m", "w": ["4.9 m", "2.45 m", "1 m"], "why": "4.9 = σ√(2 ln 20) = 2.45σ."}, {"q": "Widths east and north of 2 m each make the average square distance off …", "a": "8 m²", "w": ["4 m²", "16 m²", "2 m²"], "why": "Spreads add at right angles: σ² + σ²."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32·nav"]=[{"q": "Twice a lunar day. What is the speed of the main lunar turning?", "a": "28.984° an hour", "w": ["30.000° an hour", "15.041° an hour", "28.440° an hour"], "why": "360/12.4206."}, {"q": "The tide is a periodic function. Is the move allowed?", "a": "no: its speeds are not whole multiples of one speed", "w": ["yes: twice a day", "yes: every 12 hours", "only at springs"], "why": "No single repeat fits."}, {"q": "What is measured at each port?", "a": "the size and timing of each turning", "w": ["the speeds of the turnings", "the orbit of the Moon", "the depth of the sea"], "why": "The speeds come from the sky."}, {"q": "Over a record T, two turnings with speeds Δω apart have product at most 2/(|Δω|T). Which technique?", "a": "long-record", "w": ["turning-shadow", "right-angled-turnings", "beat"], "why": "Nearly at right angles once T is long."}, {"q": "How long do main lunar and main solar take to drift a whole turn apart?", "a": "14.77 days", "w": ["27.55 days", "182.6 days", "12.42 hours"], "why": "1/(1/12 − 1/12.4206) hours."}, {"q": "A week of record finds the main solar size. Is the move allowed?", "a": "no: it needs about 15 days", "w": ["yes: by long-record", "yes: the Sun is regular", "only at Seattle"], "why": "Over a week the two are nearly the same."}, {"q": "Springs come when?", "a": "at full and new moon", "w": ["when the Moon is nearest", "at the quarters", "at the equinox only"], "why": "The two turnings are in step."}, {"q": "Seattle: 1.07 m and 0.27 m. What is the half-range at neaps?", "a": "about 0.80 m", "w": ["about 1.34 m", "about 1.07 m", "about 0.27 m"], "why": "The sizes subtract."}, {"q": "A tide table, with surges counted beside it. What is it?", "a": "a law with a known exception rate", "w": ["a technique", "an exact forecast", "an axiom"], "why": "The weather adds what no turning holds."}, {"q": "The table is exact, so the water will reach it. Is the move allowed?", "a": "no: storms add a surge", "w": ["yes: the speeds are exact", "yes: by long-record", "only in summer"], "why": "A law with exceptions."}];

(window.LADDER_CARDS["36·nav"]=window.LADDER_CARDS["36·nav"]||[]).push(...[{"q": "Why does air scatter blue more than red?", "a": "a shaken charge sends out power as ω⁴, so as 1/λ⁴", "w": ["blue light is brighter", "red light is absorbed by water vapour", "the eye counts blue more"], "why": "34·phys’s shaken-charge technique."}, {"q": "About how many airs does sunlight cross from 5° above the horizon, in flat layers?", "a": "about 11.5", "w": ["5", "about 2", "about 90"], "why": "1/sin 5°."}, {"q": "At noon red over blue kept is about 1.19. With the sun 5° up?", "a": "about 7.7", "w": ["about 1.19", "about 0.5", "about 90"], "why": "e^((τ_blue − τ_red)/sin H)."}, {"q": "Why does the flat-layer guess fail at the horizon?", "a": "1/sin H runs off without bound; the earth’s curve keeps the path near 38 airs", "w": ["the sun is too bright there", "the air is warmer there", "it does not fail"], "why": "23·nav’s curve."}, {"q": "Skylight a right angle from the sun shakes along which line, at best?", "a": "the line square to both the sun’s ray and the line of sight", "w": ["along the sun’s ray", "along the line of sight", "every line alike"], "why": "The combed technique."}, {"q": "Through a filter turned θ from the comb’s line, what share is kept?", "a": "cos²θ", "w": ["cos θ", "sin θ", "½ always"], "why": "The two-filter technique (21·then)."}, {"q": "A cloud is over a small lagoon in a wide dark sea. Why is its green faint?", "a": "the lagoon fills a small share of the view below", "w": ["green light cannot reach clouds", "lagoons are dark", "clouds take away green"], "why": "The cloud-base technique: a mix at the shares of the view."}, {"q": "What does a bright glare on clouds tell a sailor in the far north?", "a": "ice or snow beneath", "w": ["open water beneath", "a storm coming", "the sun behind"], "why": "Ice blink: ice sends back most of the light."}, {"q": "Eye at 2 m. From about how far does a cloud base at 600 m show?", "a": "about 92 km", "w": ["about 23 km", "about 600 km", "about 5 km"], "why": "√(2R·600) + √(2R·2)."}, {"q": "Odds of land 1/9, then a sign of ratio 14. What are the odds now?", "a": "14/9", "w": ["14", "1/9 + 14", "1/126"], "why": "The odds-update technique."}, {"q": "What does the two-sign technique need of the two signs?", "a": "independent given land and given no land", "w": ["the same ratio", "that both are colours", "nothing"], "why": "30f2’s independence given."}, {"q": "Can enough signs make land certain?", "a": "no: the odds grow but the chance never reaches 1", "w": ["yes, with two signs", "yes, with ten", "yes, if each ratio is above 1"], "why": "Every ratio is finite."}]);
