(window.LADDER_CARDS["5·nav"]=window.LADDER_CARDS["5·nav"]||[]).push(
 {"u":"5·nav.1.1","q":"Why can a count of seconds be read as days, hours, minutes and seconds in exactly one way?","a":"each place is a split by its base, and one-split makes each split the only one","w":["seconds are always fewer than 60","a day has 100 000 seconds","times are rounded"],"why":"It is 4i’s place value with a base of its own for each place: 60, 60, 24."},
 {"u":"5·nav.2.1","q":"What does “modulated bases with asynchronous repetition” mean for a calendar?","a":"each place has a base of its own, and the places come round out of step","w":["every place has base ten","all the cycles end together","the calendar never repeats a day"],"why":"365 = 7 · 52 + 1, so the weekday moves one on each ordinary year."},
 {"u":"5·nav.3.1","q":"When do two cycles first come back in step?","a":"after the least common multiple of their lengths","w":["after the sum of their lengths","after the longer one","never"],"why":"The weekdays are classes of remainders by 7: add the days and take the remainder."},
 {"u":"5·nav.4.1","q":"What is a calendar’s drift?","a":"how far its average year misses the sun’s year, adding up year after year","w":["the length of its longest month","the number of leap years","the hours in its day"],"why":"The second guess, 365.25 days, runs long by about 0.0078 days a year, enough to move the spring day over the centuries."},
 {"u":"5·nav.5.1","q":"Why is the star day about 3 min 56 s shorter than the sun day?","a":"the Earth also goes round the sun, so over a year the stars gain one whole extra day","w":["the stars move faster than the sun","clocks run slow at night","the sun day is exactly 24 star hours"],"why":"A star that crosses due south at 21:00 tonight crosses near 19:02 thirty days from now."},
 {"u":"5·nav.6.1","q":"How does noon tell a ship where it is, east or west?","a":"the Earth turns once in 24 h, so the gap between local noon and home time is a share of a whole turn","w":["noon is at the same moment everywhere","the sun is higher in the west","noon comes once a week at sea"],"why":"The method depends on a clock that keeps home time."},
 {"u":"5·nav.7.1","q":"Why is “1900 was a leap year, since 4 divides 1900” a move to watch out for?","a":"100 divides 1900 and 400 does not: 1900 had 365 days","w":["4 does not divide 1900","every year is a leap year","leap years come every 7 years"],"why":"The rule in use today drops three leap years in every 400."});
